from typing import Any, Dict, Protocol

class BiometryBackend(Protocol):
    def detect_plane(self, image: Any) -> Dict: ...
    def assess_quality(self, image: Any) -> Dict: ...
    def measure_head(self, image: Any) -> Dict: ...
    def measure_abdomen(self, image: Any) -> Dict: ...
    def measure_femur(self, image: Any) -> Dict: ...
    def calculate_efw(self, hc_mm: float, ac_mm: float, fl_mm: float) -> Dict: ...
